KG42.register("clusters-a72798322448aefcb8fbbb77",{"id":"46-commercial_building_transactive_control::v142-d-K006","paper":"46-commercial_building_transactive_control","label":"RTU configures electricity supply according to demand-response services","record":{"cluster_id":"v142-d-K006","label":"RTU configures electricity supply according to demand-response services","market_meaning":"Utility selects the supply-curve configuration according to the DR service: the real-time price service updates according to the input price signal, the load-following service updates according to the input demand signal, and the demand-limiting service keeps the supply curve unchanged during the test period.","mechanism_ids":["v141-a-M02"],"market_types":["LEM"],"process_stages":["bidding"],"scope_disposition":"conditional","scope_explanation":"The three supply treatments are respectively constrained by the service type and are not applied simultaneously; the rule scope is the qualitative configuration in the RTU case, and it is not claimed that a computable numerical supply function has been provided.","assembly_status":"assembled","boundary_rationale":"The service type and external signal are identifiable inputs, Utility's supply update or fixing is the responsible activity, and the curve configuration is the result; the single Rule-Chain already has independent market meaning.","chain_bindings":[{"chain_id":"v141-c-R011","ownership":"primary","role":"core","rationale":"Fully retains the RTU service selection and the corresponding supply update and fixing branches."}],"connections":[],"object_mappings":[],"gaps":[{"gap_id":"v142-d-K006-G01","category":"ontology_extension","description":"The service objective does not yet have an independent approved object. The existing proposal for the same concept has M01 as its source scope; on that basis, service parameters cannot be transplanted to M02, nor can a demand signal be rewritten as a price signal.","chain_ids":["v141-c-R011"],"object_refs":["v141-c-R011::phi::v141-c-R011-C002","v141-c-R011::phi::v141-c-R011-C003","v141-c-R011::phi::v141-c-R011-C004"],"evidence_ids":["v141-b-g01-e12","ev-v141-b-g03-011"],"proposal_ids":["proposal:v141-b-g02-P02","proposal-v141-b-g03-dr-service-objective"],"required_work":"If a structured object for the service objective is needed, supplement M02 with same-mechanism support and manually check the proposal scope; currently retain the qualitative conditions and pending status."},{"gap_id":"v142-d-K006-G02","category":"unverified_source","description":"The service conditions and update methods are supported only by unaudited candidate evidence from M02, and the original figure of Fig. 12 and implementation details have not been verified.","chain_ids":["v141-c-R011"],"object_refs":["v141-c-R011::phi::v141-c-R011-C001","v141-c-R011::phi::v141-c-R011-C003","v141-c-R011::phi::v141-c-R011-C004"],"evidence_ids":["v141-b-g01-e12","ev-v141-b-g03-011"],"proposal_ids":[],"required_work":"Subsequently verify the original text and figures of the M02 supply design; if numerical curves are needed, perform a separate explicit extraction upstream, and do not infer curve parameters at present."}]},"rule_refs":["46-commercial_building_transactive_control::v141-c-R011"],"unresolved_rule_refs":[],"node_ids":["COMP-c619c76070af37df","COMP-e1497473e57dc523"]});
